insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-abraham_stars-4','picture',1,17,5,5,'Genesis 17:5',1,'What new name did God give Abram?',null,'["Peter", "Abraham", "Isaac", "Israel"]'::jsonb,1,'God said, "Thy name shall be Abraham; for a father of many nations have I made thee."','Read Genesis 17:5.','abraham_stars','An old man outside a desert tent gazing up at a sky full of stars.','KJV',array['abraham_stars','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Neither shall thy name any more be called Abram, but thy name shall be Abraham; for a father of many nations have I made thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-abraham_stars-5','picture',1,21,2,3,'Genesis 21:2-3',1,'Which wife of Abraham bore him Isaac in his old age?',null,'["Rebekah", "Sarah", "Rachel", "Leah"]'::jsonb,1,'Sarah conceived and bare Abraham a son in his old age, and Abraham called his name Isaac.','Read Genesis 21:2-3.','abraham_stars','An old man outside a desert tent gazing up at a sky full of stars.','KJV',array['abraham_stars','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'For Sarah conceived, and bare Abraham a son in his old age, at the set time of which God had spoken to him. And Abraham called the name of his son that was born unto him, whom Sarah bare to him, Isaac.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-joseph_coat-1','picture',1,37,3,3,'Genesis 37:3',1,'Which son received a special coat from his father Jacob (Israel)?',null,'["Samuel", "David", "Benjamin", "Joseph"]'::jsonb,3,'Israel loved Joseph more than his other children and made him a coat of many colours.','Read Genesis 37:3.','joseph_coat','A young man in a colourful coat stands in a field while older brothers watch from a distance.','KJV',array['joseph_coat','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-joseph_coat-2','picture',1,37,28,28,'Genesis 37:28',2,'To whom did Joseph''s brothers sell him?',null,'["A company of Ishmeelite merchants", "Roman traders", "Egyptian priests", "Philistine soldiers"]'::jsonb,0,'The brothers drew Joseph out of the pit and sold him to the Ishmeelites, who took him to Egypt.','Read Genesis 37:28.','joseph_coat','A young man in a colourful coat stands in a field while older brothers watch from a distance.','KJV',array['joseph_coat','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then there passed by Midianites merchantmen; and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-joseph_coat-3','picture',1,37,28,28,'Genesis 37:28',3,'For how many pieces of silver was Joseph sold?',null,'["Fifty", "Ten", "Thirty", "Twenty"]'::jsonb,3,'Genesis 37:28 records the price as twenty pieces of silver.','It is fewer than the price paid to Judas.','joseph_coat','A young man in a colourful coat stands in a field while older brothers watch from a distance.','KJV',array['joseph_coat','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then there passed by Midianites merchantmen; and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-joseph_coat-4','picture',1,37,7,7,'Genesis 37:7',2,'In Joseph''s first dream, what made obeisance to his sheaf?',null,'["The sun and the moon", "Seven ears of corn", "Eleven stars", "His brothers'' sheaves"]'::jsonb,3,'Joseph dreamed that his brothers'' sheaves stood round about and made obeisance to his sheaf. (The sun, moon and eleven stars came in his second dream.)','Read Genesis 37:7.','joseph_coat','A young man in a colourful coat stands in a field while older brothers watch from a distance.','KJV',array['joseph_coat','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'For, behold, we were binding sheaves in the field, and, lo, my sheaf arose, and also stood upright; and, behold, your sheaves stood round about, and made obeisance to my sheaf.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-joseph_coat-5','picture',1,37,33,33,'Genesis 37:33',3,'What did Jacob say when he was shown Joseph''s bloodied coat?',null,'["He is lost in the wilderness", "The Ishmeelites have taken him", "My son has run away to Egypt", "An evil beast hath devoured him"]'::jsonb,3,'Jacob knew the coat and said, "It is my son''s coat; an evil beast hath devoured him."','Read Genesis 37:33.','joseph_coat','A young man in a colourful coat stands in a field while older brothers watch from a distance.','KJV',array['joseph_coat','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And he knew it, and said, It is my son’s coat; an evil beast hath devoured him; Joseph is without doubt rent in pieces.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-moses_red_sea-1','picture',2,14,21,22,'Exodus 14:21-22',1,'Which event does this illustration show?',null,'["Noah''s flood", "Israel crossing the Red Sea", "Jonah and the great fish", "Jesus calming the storm"]'::jsonb,1,'The waters were divided and Israel went into the midst of the sea upon dry ground.','Read Exodus 14:21-22.','moses_red_sea','A leader raises his staff as the sea parts into towering walls and people cross on dry ground.','KJV',array['moses_red_sea','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Moses stretched out his hand over the sea; and the LORD caused the sea to go back by a strong east wind all that night, and made the sea dry land, and the waters were divided. And the children of Israel went into the midst of the sea upon the dry ground: and the waters were a wall unto them on their right hand, and on their left.',null,null) on conflict (id) do nothing;
