insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-pentecost-3','picture',44,2,14,14,'Acts 2:14',1,'Which apostle stood up and preached to the crowd that day?',null,'["John", "Stephen", "Peter", "Paul"]'::jsonb,2,'Peter, standing up with the eleven, lifted up his voice.','Read Acts 2:14.','pentecost','Men and women in a room with small flames resting above their heads.','KJV',array['pentecost','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'But Peter, standing up with the eleven, lifted up his voice, and said unto them, Ye men of Judæa, and all ye that dwell at Jerusalem, be this known unto you, and hearken to my words:',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-pentecost-4','picture',44,2,41,41,'Acts 2:41',3,'About how many souls were added that day?',null,'["About three thousand", "About one hundred and twenty", "About five hundred", "About five thousand"]'::jsonb,0,'Acts 2:41 reports about three thousand souls added. (Five thousand is Acts 4:4.)','Read Acts 2:41.','pentecost','Men and women in a room with small flames resting above their heads.','KJV',array['pentecost','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then they that gladly received his word were baptized: and the same day there were added unto them about three thousand souls.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-paul_ship-1','picture',44,27,42,44,'Acts 27:42-44',1,'Which apostle survived this shipwreck while being taken to Rome?',null,'["Peter", "Paul", "Timothy", "Barnabas"]'::jsonb,1,'The centurion, willing to save Paul, kept the soldiers from their purpose, and all escaped safe to land.','Read Acts 27:42-44.','paul_ship','A Roman ship breaks apart on rocks while passengers swim toward an island beach.','KJV',array['paul_ship','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And the soldiers’ counsel was to kill the prisoners, lest any of them should swim out, and escape. But the centurion, willing to save Paul, kept them from their purpose; and commanded that they which could swim should cast themselves first into the sea, and get to land: And the rest, some on boards, and some on broken pieces of the ship. And so it came to pass, that they escaped all safe to land.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-paul_ship-2','picture',44,28,1,1,'Acts 28:1',3,'On which island did the shipwrecked company land?',null,'["Melita", "Cyprus", "Patmos", "Crete"]'::jsonb,0,'"They knew that the island was called Melita" (commonly identified with Malta).','Read Acts 28:1.','paul_ship','A Roman ship breaks apart on rocks while passengers swim toward an island beach.','KJV',array['paul_ship','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And when they were escaped, then they knew that the island was called Melita.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-paul_ship-3','picture',44,28,3,3,'Acts 28:3',2,'What fastened on Paul''s hand as he gathered sticks on the island?',null,'["A viper", "A crab", "A spider", "A scorpion"]'::jsonb,0,'A viper came out of the heat and fastened on his hand, but he felt no harm.','Read Acts 28:3.','paul_ship','A Roman ship breaks apart on rocks while passengers swim toward an island beach.','KJV',array['paul_ship','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And when Paul had gathered a bundle of sticks, and laid them on the fire, there came a viper out of the heat, and fastened on his hand.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-paul_ship-4','picture',44,28,16,16,'Acts 28:16',2,'Which city was Paul finally brought to as a prisoner?',null,'["Rome", "Corinth", "Athens", "Ephesus"]'::jsonb,0,'"When we came to Rome... Paul was suffered to dwell by himself with a soldier."','Read Acts 28:16.','paul_ship','A Roman ship breaks apart on rocks while passengers swim toward an island beach.','KJV',array['paul_ship','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And when we came to Rome, the centurion delivered the prisoners to the captain of the guard: but Paul was suffered to dwell by himself with a soldier that kept him.',null,null) on conflict (id) do nothing;
