insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-moses_red_sea-6','picture',2,14,21,21,'Exodus 14:21',2,'What did the LORD use to drive the sea back all night?',null,'["A cold north wind", "A strong east wind", "A whirlwind", "A great earthquake"]'::jsonb,1,'The LORD caused the sea to go back by a strong east wind all that night.','Read Exodus 14:21.','moses_red_sea','A leader raises his staff as the sea parts into towering walls and people cross on dry ground.','KJV',array['moses_red_sea','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Moses stretched out his hand over the sea; and the LORD caused the sea to go back by a strong east wind all that night, and made the sea dry land, and the waters were divided.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-moses_red_sea-7','picture',2,14,28,28,'Exodus 14:28',1,'What happened to Pharaoh''s army when the waters returned?',null,'["They were struck blind", "They turned back to Egypt", "They crossed safely", "The sea covered them"]'::jsonb,3,'The waters returned and covered the chariots, the horsemen and all the host of Pharaoh.','Read Exodus 14:28.','moses_red_sea','A leader raises his staff as the sea parts into towering walls and people cross on dry ground.','KJV',array['moses_red_sea','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And the waters returned, and covered the chariots, and the horsemen, and all the host of Pharaoh that came into the sea after them; there remained not so much as one of them.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-moses_red_sea-8','picture',2,15,23,25,'Exodus 15:23-25',3,'Where did Moses make bitter waters sweet soon after the crossing?',null,'["Marah", "Meribah", "The pool of Siloam", "The river Jordan"]'::jsonb,0,'The waters of Marah were bitter; Moses cast a tree into them and they were made sweet.','Read Exodus 15:23-25.','moses_red_sea','A leader raises his staff as the sea parts into towering walls and people cross on dry ground.','KJV',array['moses_red_sea','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And when they came to Marah, they could not drink of the waters of Marah, for they were bitter: therefore the name of it was called Marah. And the people murmured against Moses, saying, What shall we drink? And he cried unto the LORD; and the LORD shewed him a tree, which when he had cast into the waters, the waters were made sweet: there he made for them a statute and an ordinance, and there he proved them,',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-david_goliath-6','picture',9,17,38,39,'1 Samuel 17:38-39',2,'Whose armour did David try on before facing Goliath?',null,'["Saul''s", "Abner''s", "Goliath''s", "Jonathan''s"]'::jsonb,0,'Saul armed David with his armour, but David put it off because he had not proved it.','Read 1 Samuel 17:38-39.','david_goliath','A young shepherd with a sling faces an armoured giant in a valley between two armies.','KJV',array['david_goliath','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Saul armed David with his armour, and he put an helmet of brass upon his head; also he armed him with a coat of mail. And David girded his sword upon his armour, and he assayed to go; for he had not proved it. And David said unto Saul, I cannot go with these; for I have not proved them. And David put them off him.',null,null) on conflict (id) do nothing;
