insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-solomon_temple-8','picture',11,5,8,10,'1 Kings 5:8-10',2,'Which king of Tyre sent cedar and fir timber for the temple?',null,'["Hiram", "Cyrus", "Nebuchadnezzar", "Ahab"]'::jsonb,0,'Hiram gave Solomon cedar trees and fir trees according to all his desire.','Read 1 Kings 5:8-10.','solomon_temple','A king in royal robes before a grand temple with bronze pillars as offerings smoke.','KJV',array['solomon_temple','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Hiram sent to Solomon, saying, I have considered the things which thou sentest to me for: and I will do all thy desire concerning timber of cedar, and concerning timber of fir. My servants shall bring them down from Lebanon unto the sea: and I will convey them by sea in floats unto the place that thou shalt appoint me, and will cause them to be discharged there, and thou shalt receive them: and thou shalt accomplish my desire, in giving food for my household. So Hiram gave Solomon cedar trees and fir trees according to all his desire.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-elijah_carmel-6','picture',11,18,21,21,'1 Kings 18:21',2,'On Carmel Elijah asked, "How long halt ye between two..."',null,'["Kings", "Altars", "Mountains", "Opinions"]'::jsonb,3,'"How long halt ye between two opinions? if the LORD be God, follow him."','Read 1 Kings 18:21.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Elijah came unto all the people, and said, How long halt ye between two opinions? if the LORD be God, follow him: but if Baal, then follow him. And the people answered him not a word.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-elijah_carmel-7','picture',11,18,33,35,'1 Kings 18:33-35',3,'What did Elijah have poured over the sacrifice on Mount Carmel?',null,'["Wine", "Oil", "Water", "Blood"]'::jsonb,2,'Barrels of water were poured on the sacrifice three times until the trench was filled.','Read 1 Kings 18:33-35.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And he put the wood in order, and cut the bullock in pieces, and laid him on the wood, and said, Fill four barrels with water, and pour it on the burnt sacrifice, and on the wood. And he said, Do it the second time. And they did it the second time. And he said, Do it the third time. And they did it the third time. And the water ran round about the altar; and he filled the trench also with water.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-elijah_carmel-8','picture',11,18,31,31,'1 Kings 18:31',2,'How many stones did Elijah use to build the altar on Carmel?',null,'["Ten", "Three", "Seven", "Twelve"]'::jsonb,3,'Elijah took twelve stones, according to the number of the tribes of the sons of Jacob.','Read 1 Kings 18:31.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Elijah took twelve stones, according to the number of the tribes of the sons of Jacob, unto whom the word of the LORD came, saying, Israel shall be thy name:',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-daniel_lions-6','picture',27,6,13,13,'Daniel 6:13',2,'Why was Daniel cast into the den of lions?',null,'["He refused the king''s meat", "He kept praying to his God despite the king''s decree", "He would not bow to a golden image", "He read the writing on the wall"]'::jsonb,1,'His accusers said Daniel regarded not the king''s decree but made his petition three times a day.','Read Daniel 6:13.','daniel_lions','A calm man in robes stands among resting lions in a dim stone den.','KJV',array['daniel_lions','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then answered they and said before the king, That Daniel, which is of the children of the captivity of Judah, regardeth not thee, O king, nor the decree that thou hast signed, but maketh his petition three times a day.',null,null) on conflict (id) do nothing;
