insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-empty_tomb-7','picture',43,20,2,4,'John 20:2-4',3,'Who ran with Peter to the tomb and got there first?',null,'["Thomas", "James", "Andrew", "The other disciple, whom Jesus loved"]'::jsonb,3,'The other disciple, whom Jesus loved, did outrun Peter and came first to the sepulchre.','Read John 20:2-4.','empty_tomb','Women carrying spices approach a rock-cut tomb whose stone has been rolled away.','KJV',array['empty_tomb','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then she runneth, and cometh to Simon Peter, and to the other disciple, whom Jesus loved, and saith unto them, They have taken away the Lord out of the sepulchre, and we know not where they have laid him. Peter therefore went forth, and that other disciple, and came to the sepulchre. So they ran both together: and the other disciple did outrun Peter, and came first to the sepulchre.',null,null) on conflict (id) do nothing;
