insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-sinai_tablets-1','picture',2,32,15,15,'Exodus 32:15',1,'Which event does this illustration depict?',null,'["Elijah at Horeb", "Abraham on Mount Moriah", "Joshua at Jericho", "Moses bringing the tables of the testimony down from the mount"]'::jsonb,3,'Moses turned, and went down from the mount, and the two tables of the testimony were in his hand (Exodus 32:15).','Read Exodus 32:15.','sinai_tablets','Moses comes down a smoking mountain carrying two stone tablets, with a camp of tents in the valley below.','KJV',array['sinai_tablets','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text for illustration batch 2; automatic checks (reference exists, keywords found in the KJV passage, tap areas within the picture); independent AI review against the KJV text (Claude Opus 5.5), 22 of 165 items flagged and fixed then re-reviewed, 1 dropped. Hidden-object areas were drawn by hand on a 10% grid over each illustration and checked visually on a contact sheet. See tests/review/illustrations2."}'::jsonb,'And Moses turned, and went down from the mount, and the two tables of the testimony were in his hand: the tables were written on both their sides; on the one side and on the other were they written.',null,null) on conflict (id) do nothing;
