insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-sinai_tablets-4','picture',2,32,19,19,'Exodus 32:19',3,'What did Moses see as he came near the camp?',null,'["The people building the tabernacle", "Joshua''s army in battle", "A pillar of cloud", "The calf, and the dancing"]'::jsonb,3,'As soon as he came nigh unto the camp, he saw the calf, and the dancing: and he cast the tables out of his hands (Exodus 32:19).','Read Exodus 32:19.','sinai_tablets','Moses comes down a smoking mountain carrying two stone tablets, with a camp of tents in the valley below.','KJV',array['sinai_tablets','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text for illustration batch 2; automatic checks (reference exists, keywords found in the KJV passage, tap areas within the picture); independent AI review against the KJV text (Claude Opus 5.5), 22 of 165 items flagged and fixed then re-reviewed, 1 dropped. Hidden-object areas were drawn by hand on a 10% grid over each illustration and checked visually on a contact sheet. See tests/review/illustrations2."}'::jsonb,'And it came to pass, as soon as he came nigh unto the camp, that he saw the calf, and the dancing: and Moses’ anger waxed hot, and he cast the tables out of his hands, and brake them beneath the mount.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('pic-parable_sower-1','picture',40,13,3,4,'Matthew 13:3-4',1,'Which parable does this illustration show?',null,'["The parable of the mustard seed", "The parable of the tares", "The parable of the sower", "The parable of the lost sheep"]'::jsonb,2,'Jesus said, “Behold, a sower went forth to sow”; some seed fell by the way side, and the fowls devoured it (Matthew 13:3-4).','Read Matthew 13:3-4.','parable_sower','A farmer scatters seed over a field with a path where birds eat seed, stony ground, thorns and good soil.','KJV',array['parable_sower','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text for illustration batch 2; automatic checks (reference exists, keywords found in the KJV passage, tap areas within the picture); independent AI review against the KJV text (Claude Opus 5.5), 22 of 165 items flagged and fixed then re-reviewed, 1 dropped. Hidden-object areas were drawn by hand on a 10% grid over each illustration and checked visually on a contact sheet. See tests/review/illustrations2."}'::jsonb,'And he spake many things unto them in parables, saying, Behold, a sower went forth to sow; And when he sowed, some seeds fell by the way side, and the fowls came and devoured them up:',null,null) on conflict (id) do nothing;
