insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('seq-paul_philippi','sequence',44,16,14,14,'Acts 16:14-33',2,'Put these events in order: Paul and Silas at Philippi',null,'["The Lord opens Lydia''s heart", "Paul casts the spirit out of a damsel", "Paul and Silas are cast into prison", "At midnight they pray and sing praises", "The jailer and all his household are baptized"]'::jsonb,0,'The Lord opens Lydia''s heart (Acts 16:14) → Paul casts the spirit out of a damsel (Acts 16:18) → Paul and Silas are cast into prison (Acts 16:23) → At midnight they pray and sing praises (Acts 16:25) → The jailer and all his household are baptized (Acts 16:33)','The first event is in Acts 16:14.',null,null,'KJV',array['paul_philippi','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'Acts 16:14: And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul.
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-1','wisdom',20,15,1,1,'Proverbs 15:1',1,'In a team meeting, a frustrated coworker loudly blames you for a missed deadline that was not entirely your fault. Everyone turns to see how you will react. Which response best reflects the teaching of Proverbs 15:1?',null,'["List every mistake the coworker has made this quarter to put them in their place", "Raise your voice to match theirs so everyone knows you will not be pushed around", "Answer calmly and gently, acknowledging the frustration and offering to work out the problem together", "Make a sarcastic remark that gets a laugh from the room at their expense"]'::jsonb,2,'Proverbs 15:1 teaches that "a soft answer turneth away wrath: but grievous words stir up anger." A gentle reply calms the situation, while harsh or cutting words make it worse.','The verse contrasts two kinds of answers and what each one does to anger.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'A soft answer turneth away wrath: but grievous words stir up anger.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-2','wisdom',49,4,25,25,'Ephesians 4:25',1,'A friend asks whether you liked the business plan they emailed you. You found serious problems in it, and a quick ''It''s great!'' would be much easier. What does Ephesians 4:25 counsel here?',null,'["Speak the truth to them, because you are members one of another", "Praise it to their face but tell others what you really think", "Say nothing and simply stop replying to their messages", "Tell them it is perfect so you avoid an awkward conversation"]'::jsonb,0,'Ephesians 4:25 says, "putting away lying, speak every man truth with his neighbour: for we are members one of another." Honest speech, not a convenient falsehood, is the instruction.','The verse gives a reason for honesty based on how believers are joined together.',null,null,'KJV',array['wisdom','Ephesians']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Wherefore putting away lying, speak every man truth with his neighbour: for we are members one of another.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-3','wisdom',20,11,13,13,'Proverbs 11:13',2,'A close colleague confides that they are struggling with a personal matter and asks you to keep it private. Later, over lunch, others start guessing about why the colleague seems distracted. According to Proverbs 11:13, what should you do?',null,'["Keep the matter to yourself, as a person of a faithful spirit would", "Reveal it only to the one coworker you trust most", "Share what you know so the group understands and can be sympathetic", "Drop hints without saying it outright, so you technically keep the secret"]'::jsonb,0,'Proverbs 11:13 contrasts the talebearer who "revealeth secrets" with one "of a faithful spirit" who "concealeth the matter." Keeping the confidence is the faithful choice.','The verse contrasts two kinds of people by what they do with secrets.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'A talebearer revealeth secrets: but he that is of a faithful spirit concealeth the matter.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-4','wisdom',40,5,37,37,'Matthew 5:37',2,'A client keeps asking whether you will really deliver on Friday. You are tempted to pile on dramatic assurances like ''I swear on everything I have'' to sound more convincing. Which approach best reflects Matthew 5:37?',null,'["Avoid giving any clear answer so you cannot be held to it", "Use the strongest guarantees you can think of so the client feels secure", "Promise Friday now and quietly plan to explain later if it slips", "Give a plain, honest ''yes'' or ''no'' and let your word stand on its own"]'::jsonb,3,'In Matthew 5:37 Jesus says, "let your communication be, Yea, yea; Nay, nay: for whatsoever is more than these cometh of evil." A simple, truthful answer is what He teaches.','Jesus describes how plain a trustworthy answer should be.',null,null,'KJV',array['wisdom','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But let your communication be, Yea, yea; Nay, nay: for whatsoever is more than these cometh of evil.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-5','wisdom',21,5,4,5,'Ecclesiastes 5:4-5',3,'Months ago, during a moving worship service, you made a sincere vow to God to give a specific gift to a ministry. Since then you keep putting it off, half-wondering whether a vow made in the moment really counts. What does Ecclesiastes 5:4-5 counsel?',null,'["Make a larger vow to make up for the unpaid one", "Keep postponing indefinitely, since God does not mind delays", "Fulfil what you vowed without delay, since it is better not to vow than to vow and not pay", "Consider the vow cancelled because it was made in an emotional moment"]'::jsonb,2,'Ecclesiastes 5:4-5 says, "When thou vowest a vow unto God, defer not to pay it... Better is it that thou shouldest not vow, than that thou shouldest vow and not pay." A vow should be kept, and kept promptly.','The passage speaks both about timing and about whether vowing at all is wise.',null,null,'KJV',array['wisdom','Ecclesiastes']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'When thou vowest a vow unto God, defer not to pay it; for he hath no pleasure in fools: pay that which thou hast vowed. Better is it that thou shouldest not vow, than that thou shouldest vow and not pay.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-6','wisdom',20,26,20,20,'Proverbs 26:20',3,'Two family members are feuding, and each one calls you to vent about the other and pass along what was said. You notice the conflict grows every time comments get relayed between them. Which response best reflects Proverbs 26:20?',null,'["Post about the feud online to get outside opinions", "Pass along each side''s remarks accurately so both stay informed", "Tell each person the other said worse things than they did, to speed up a showdown", "Refuse to carry stories between them, letting the quarrel lose its fuel"]'::jsonb,3,'Proverbs 26:20 says, "Where no wood is, there the fire goeth out: so where there is no talebearer, the strife ceaseth." Refusing to carry tales removes the fuel that keeps strife burning.','Think about what happens to a fire when no more wood is added.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Where no wood is, there the fire goeth out: so where there is no talebearer, the strife ceaseth.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-7','wisdom',19,15,4,4,'Psalms 15:4',4,'You agreed to sell your car to a neighbour at a set price and shook hands on it. Before the transfer, someone else offers you considerably more. Which response best reflects the character described in Psalms 15:4?',null,'["Invent a mechanical problem so you can back out gracefully", "Keep your word to the neighbour even though it now costs you", "Tell the neighbour they must match the new price or lose the deal", "Accept the higher offer, since nothing has been signed yet"]'::jsonb,1,'Psalms 15:4 describes the one who may dwell with the LORD as "He that sweareth to his own hurt, and changeth not." Such a person keeps a commitment even when it becomes costly.','The psalm praises someone whose promise holds even when keeping it hurts.',null,null,'KJV',array['wisdom','Psalms']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'In whose eyes a vile person is contemned; but he honoureth them that fear the LORD. He that sweareth to his own hurt, and changeth not.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w1-8','wisdom',20,18,17,17,'Proverbs 18:17',4,'A friend tells you a convincing story about how a mutual acquaintance cheated them, and you feel ready to share it and take sides. You have not heard from the other person at all. What does Proverbs 18:17 counsel here?',null,'["Confront the acquaintance publicly so the truth comes out quickly", "Recognize that the first account can seem right until the other side is examined, and withhold judgment", "Trust the first account fully, since a friend would not mislead you", "Warn others about the acquaintance right away to protect them"]'::jsonb,1,'Proverbs 18:17 says, "He that is first in his own cause seemeth just; but his neighbour cometh and searcheth him." A one-sided story can sound right until it is examined, so judgment and repetition should wait.','The verse notes how a case can appear before anyone questions it.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that is first in his own cause seemeth just; but his neighbour cometh and searcheth him.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-1','wisdom',20,15,1,1,'Proverbs 15:1',1,'A frustrated customer calls your desk and starts shouting about a billing mistake that wasn''t your fault. You feel your own temper rising. Which response best reflects the teaching of Proverbs 15:1?',null,'["Point out sharply that the mistake was someone else''s fault", "Raise your voice to match theirs so they know you won''t be pushed around", "Hang up and let them call back when they''ve cooled off", "Answer calmly and gently while you work toward a solution"]'::jsonb,3,'Proverbs 15:1 teaches that ''a soft answer turneth away wrath: but grievous words stir up anger,'' so a gentle reply calms the conflict.','This verse contrasts two kinds of answers and what each one does to anger.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'A soft answer turneth away wrath: but grievous words stir up anger.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-2','wisdom',49,4,26,26,'Ephesians 4:26',1,'You and your spouse had a heated disagreement about household chores after dinner. It''s getting late, and you''re tempted to go to bed still fuming and deal with it ''someday.'' What does Ephesians 4:26 counsel here?',null,'["Sleep in another room until the other person apologizes first", "Let the anger simmer for a few days so the other person learns a lesson", "Pretend nothing happened and never bring the issue up again", "Deal with your anger promptly rather than letting it carry on unresolved"]'::jsonb,3,'Ephesians 4:26 says, ''Be ye angry, and sin not: let not the sun go down upon your wrath,'' urging that anger be dealt with quickly rather than nursed.','The verse uses the end of the day as a time marker for anger.',null,null,'KJV',array['wisdom','Ephesians']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Be ye angry, and sin not: let not the sun go down upon your wrath:',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-3','wisdom',59,1,19,20,'James 1:19-20',2,'In a team meeting, a coworker criticizes a project you led. Before they finish explaining, you''re already forming a sharp rebuttal in your head. Which response best reflects James 1:19-20?',null,'["Respond with a forceful counterattack to show you''re confident", "Stay silent in the meeting, then vent angrily about them afterward", "Listen carefully to the full concern before answering, and keep your anger in check", "Interrupt immediately so the criticism doesn''t spread to others"]'::jsonb,2,'James 1:19-20 calls us to be ''swift to hear, slow to speak, slow to wrath,'' because ''the wrath of man worketh not the righteousness of God.''','James lists three things to be quick or slow about, in a specific order.',null,null,'KJV',array['wisdom','James']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath: For the wrath of man worketh not the righteousness of God.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-4','wisdom',40,5,23,24,'Matthew 5:23-24',2,'You''re heading to a worship service, ready to give an offering, when you remember that a friend is still hurt by a harsh comment you made last week. What does Jesus teach in Matthew 5:23-24?',null,'["Give a larger offering to make up for the harsh comment", "Wait for your friend to come to you, since they''re the one upset", "Focus only on your worship; relationships are a separate matter", "Go and seek to be reconciled with your friend as a priority"]'::jsonb,3,'In Matthew 5:23-24 Jesus says to leave the gift, ''first be reconciled to thy brother, and then come and offer thy gift.''','Jesus tells the worshipper what to do before offering at the altar.',null,null,'KJV',array['wisdom','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Therefore if thou bring thy gift to the altar, and there rememberest that thy brother hath ought against thee; Leave there thy gift before the altar, and go thy way; first be reconciled to thy brother, and then come and offer thy gift.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-5','wisdom',45,12,17,21,'Romans 12:17-21',3,'A neighbor spread false rumors about you in your community group. Later you learn that their family has fallen on hard times and is struggling to afford groceries. Which response best reflects Romans 12:17-21?',null,'["Quietly work to get them removed from the community group", "Share the news of their hardship in the group so they feel what you felt", "Refuse to take revenge and instead offer practical help, like food", "Ignore them entirely, since they brought this on themselves"]'::jsonb,2,'Romans 12:19-21 says ''avenge not yourselves'' and ''if thine enemy hunger, feed him,'' concluding, ''overcome evil with good.''','Paul describes what to do if an enemy is hungry or thirsty.',null,null,'KJV',array['wisdom','Romans']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Recompense to no man evil for evil. Provide things honest in the sight of all men. If it be possible, as much as lieth in you, live peaceably with all men. Dearly beloved, avenge not yourselves, but rather give place unto wrath: for it is written, Vengeance is mine; I will repay, saith the Lord. Therefore if thine enemy hunger, feed him; if he thirst, give him drink: for in so doing thou shalt heap coals of fire on his head. Be not overcome of evil, but overcome evil with good.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-6','wisdom',20,17,14,14,'Proverbs 17:14',3,'A minor disagreement with your sibling over splitting a restaurant bill is starting to escalate, and old grievances are creeping into the conversation. What does Proverbs 17:14 counsel here?',null,'["Drop the quarrel early, before it grows into something bigger", "Bring up every past grievance now so everything is finally aired", "Insist on settling the exact amount, no matter how long it takes", "Keep arguing but lower your voice so it seems more reasonable"]'::jsonb,0,'Proverbs 17:14 compares ''the beginning of strife'' to letting out water, so we should ''leave off contention, before it be meddled with.''','The verse compares a quarrel''s start to a small breach that releases water.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'The beginning of strife is as when one letteth out water: therefore leave off contention, before it be meddled with.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-7','wisdom',20,26,17,17,'Proverbs 26:17',4,'Walking through the office, you overhear two colleagues from another department arguing over a matter that has nothing to do with you. You''re tempted to jump in and tell them who''s right. Which response best reflects Proverbs 26:17?',null,'["Tell other coworkers about the argument so everyone''s aware", "Step in and take a side, since you clearly know who''s right", "Report both of them to their manager to show initiative", "Stay out of a quarrel that doesn''t belong to you"]'::jsonb,3,'Proverbs 26:17 says he ''that passeth by, and meddleth with strife belonging not to him, is like one that taketh a dog by the ears''—inviting needless trouble.','The proverb uses a vivid picture involving an animal to describe interfering.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that passeth by, and meddleth with strife belonging not to him, is like one that taketh a dog by the ears.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w3-8','wisdom',21,7,21,22,'Ecclesiastes 7:21-22',4,'A friend tells you that someone at work grumbled about you behind your back. You feel stung and start planning to confront them over every word. Which response best reflects Ecclesiastes 7:21-22?',null,'["Start grumbling about them too, so things are even", "Ask your friend to keep reporting anything else said about you", "Track down exactly what was said so you can respond point by point", "Don''t dwell on every remark, remembering you have spoken against others too"]'::jsonb,3,'Ecclesiastes 7:21-22 advises to ''take no heed unto all words that are spoken,'' because ''thine own heart knoweth that thou thyself likewise hast cursed others.''','The Preacher appeals to your own conscience about your past words.',null,null,'KJV',array['wisdom','Ecclesiastes']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Also take no heed unto all words that are spoken; lest thou hear thy servant curse thee: For oftentimes also thine own heart knoweth that thou thyself likewise hast cursed others.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-1','wisdom',20,16,18,18,'Proverbs 16:18',1,'You have just landed the biggest client in your company''s history, and you start telling coworkers that the team couldn''t function without you. You feel untouchable and stop double-checking your work. Which attitude best reflects the teaching of Proverbs 16:18?',null,'["Make sure everyone knows the win was yours before someone else claims it", "Recognize that a haughty spirit sets you up for a fall, and stay humble and careful", "Relax your standards, since past success guarantees future success", "Enjoy the moment, because success shows that your pride is justified"]'::jsonb,1,'Proverbs 16:18 warns that "Pride goeth before destruction, and an haughty spirit before a fall." Humility and care guard against the fall that pride invites.','This verse links an inner attitude to an outcome that soon follows it.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Pride goeth before destruction, and an haughty spirit before a fall.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-2','wisdom',20,12,15,15,'Proverbs 12:15',1,'You are planning to put most of your savings into a new business idea. A trusted friend with years of experience offers to review your plan, but you are already certain it will work. What does Proverbs 12:15 counsel here?',null,'["Decline the review, because confidence in your own judgment is enough", "Ask for advice only after the money is spent", "Listen to your friend''s counsel before deciding", "Go ahead quickly so doubts don''t slow you down"]'::jsonb,2,'Proverbs 12:15 says "The way of a fool is right in his own eyes: but he that hearkeneth unto counsel is wise." The wise person listens to advice instead of trusting only their own view.','Notice the contrast between someone sure of themselves and someone who listens.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'The way of a fool is right in his own eyes: but he that hearkeneth unto counsel is wise.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-3','wisdom',20,27,2,2,'Proverbs 27:2',2,'During your annual review, you are tempted to spend the meeting listing all your accomplishments and describing yourself as the best performer on the team. Your manager has already noticed much of your work. Which response best reflects the teaching of Proverbs 27:2?',null,'["Praise yourself boldly, since no one else will speak up for you", "Answer honestly and let others, rather than your own mouth, do the praising", "Post your achievements online so strangers will admire you", "Belittle your coworkers so your own work looks better"]'::jsonb,1,'Proverbs 27:2 teaches, "Let another man praise thee, and not thine own mouth." Praise is fitting when it comes from others, not from self-promotion.','The verse is about whose lips should speak your praise.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Let another man praise thee, and not thine own mouth; a stranger, and not thine own lips.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-4','wisdom',20,15,22,22,'Proverbs 15:22',2,'Your family is deciding whether to move across the country for a new job. You are inclined to make the decision alone so no one complicates things. What does Proverbs 15:22 counsel here?',null,'["Make the decision first and inform everyone afterward", "Decide quietly by yourself, because more voices only cause confusion", "Seek counsel from several wise, trusted people before deciding", "Ask only one person who is sure to agree with you"]'::jsonb,2,'Proverbs 15:22 says "Without counsel purposes are disappointed: but in the multitude of counsellors they are established." Plans are made firm by seeking many wise advisers.','The verse contrasts plans made with no input against plans made with many voices.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Without counsel purposes are disappointed: but in the multitude of counsellors they are established.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-5','wisdom',20,12,1,1,'Proverbs 12:1',3,'A colleague points out, privately and kindly, a serious error in a report you submitted. Your first instinct is to feel insulted and to avoid them. Which response best reflects the teaching of Proverbs 12:1?',null,'["Defend the report, since admitting fault damages your reputation", "Ignore the feedback and wait for the issue to be forgotten", "Welcome the correction as a way to learn, rather than resenting it", "Report the colleague for overstepping"]'::jsonb,2,'Proverbs 12:1 says "Whoso loveth instruction loveth knowledge: but he that hateth reproof is brutish." Loving correction is the path to knowledge, while hating it is called brutish.','The verse describes the person who hates reproof in very unflattering terms.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Whoso loveth instruction loveth knowledge: but he that hateth reproof is brutish.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-6','wisdom',45,12,16,16,'Romans 12:16',3,'At a neighborhood gathering, you notice yourself spending time only with the most successful and influential guests while ignoring a quiet newcomer who seems to be struggling. You also find yourself privately feeling smarter than most people there. What does Romans 12:16 counsel here?',null,'["Associate with those of low estate and do not be wise in your own conceits", "Focus on networking with people who can raise your status", "Trust your sense of superiority, since it reflects real wisdom", "Keep your distance from the newcomer so you don''t seem lowly"]'::jsonb,0,'Romans 12:16 says "Mind not high things, but condescend to men of low estate. Be not wise in your own conceits." Believers are to associate with the lowly and avoid thinking too highly of their own wisdom.','Paul addresses both who you spend time with and how you view your own wisdom.',null,null,'KJV',array['wisdom','Romans']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Be of the same mind one toward another. Mind not high things, but condescend to men of low estate. Be not wise in your own conceits.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-7','wisdom',21,4,13,13,'Ecclesiastes 4:13',4,'You have led your department for twenty years. A young new hire respectfully suggests a better process, and you are tempted to dismiss it simply because of your seniority and long experience. Which response best reflects the teaching of Ecclesiastes 4:13?',null,'["Stay teachable and open to admonition, regardless of your rank or age", "Wait until the new hire has earned enough years before listening", "Accept advice only from people who are older than you", "Dismiss the idea, since age and position always outweigh youth"]'::jsonb,0,'Ecclesiastes 4:13 says "Better is a poor and a wise child than an old and foolish king, who will no more be admonished." Position and age are worth less than wisdom when a person refuses correction.','The verse compares a young person and a ruler, and what makes the ruler foolish.',null,null,'KJV',array['wisdom','Ecclesiastes']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Better is a poor and a wise child than an old and foolish king, who will no more be admonished.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w6-8','wisdom',20,25,6,7,'Proverbs 25:6-7',4,'At a formal company dinner, you arrive early and are tempted to sit at the head table beside the CEO, even though no one has invited you there. What does Proverbs 25:6-7 counsel here?',null,'["Take the best seat early, since boldness gets you noticed", "Sit near the CEO and wait to see whether anyone objects", "Stand beside the important guests so you look important too", "Take a modest place and let your host invite you higher"]'::jsonb,3,'Proverbs 25:6-7 says "Put not forth thyself in the presence of the king," for it is better to be told "Come up hither" than to be put lower. Humbly waiting to be honored is better than being publicly demoted.','The passage compares two ways of being moved by your host, one honorable and one embarrassing.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Put not forth thyself in the presence of the king, and stand not in the place of great men: For better it is that it be said unto thee, Come up hither; than that thou shouldest be put lower in the presence of the prince whom thine eyes have seen.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-1','wisdom',20,15,1,1,'Proverbs 15:1',1,'Your sister calls, upset and accusing you of forgetting her birthday dinner. You feel unfairly blamed because the date was changed without telling you. Which response best reflects the teaching of Proverbs 15:1?',null,'["Hang up and refuse to discuss it until she apologises", "Raise your voice so she understands she is the one at fault", "Answer her gently and calmly, acknowledging her hurt before explaining the mix-up", "Point out sharply all the times she has forgotten your plans"]'::jsonb,2,'Proverbs 15:1 teaches that ''a soft answer turneth away wrath: but grievous words stir up anger,'' so a gentle reply is the wise path.','The verse contrasts two kinds of words and what each one does to anger.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'A soft answer turneth away wrath: but grievous words stir up anger.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-2','wisdom',49,4,26,26,'Ephesians 4:26',1,'You and your spouse had a heated disagreement about household chores this evening. It is getting late, and you are tempted to go to bed still fuming and deal with it ''some other time.'' What does Ephesians 4:26 counsel here?',null,'["Vent to friends over the next few days while staying angry at your spouse", "Say nothing, but quietly keep holding on to your resentment", "Deal with the anger without sinning and seek to settle it before the day ends", "Let the anger simmer for a few days so your spouse learns a lesson"]'::jsonb,2,'Ephesians 4:26 says, ''Be ye angry, and sin not: let not the sun go down upon your wrath.'' Anger is not to lead to sin, nor to be carried past the end of the day. It should be dealt with promptly rather than nursed.','Think about what the verse says regarding the end of the day.',null,null,'KJV',array['wisdom','Ephesians']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Be ye angry, and sin not: let not the sun go down upon your wrath:',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-3','wisdom',40,5,23,24,'Matthew 5:23-24',2,'You are about to take part in a worship service when you remember that a close friend is still hurt by a careless remark you made last week. You would rather just focus on the service and let things blow over. What does Matthew 5:23-24 counsel here?',null,'["Give a larger offering to make up for the remark", "Carry on with your offering, since worship matters more than the friendship", "First go and be reconciled with your friend, then come and offer your gift", "Wait for your friend to come to you, since they are the one upset"]'::jsonb,2,'In Matthew 5:23-24 Jesus says to ''leave there thy gift before the altar'' and ''first be reconciled to thy brother, and then come and offer thy gift.''','Notice the order of actions Jesus gives in the passage.',null,null,'KJV',array['wisdom','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Therefore if thou bring thy gift to the altar, and there rememberest that thy brother hath ought against thee; Leave there thy gift before the altar, and go thy way; first be reconciled to thy brother, and then come and offer thy gift.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-4','wisdom',45,12,15,15,'Romans 12:15',2,'A neighbour shares joyful news about her new grandchild, and later the same week another neighbour tells you his father has died. You are busy and tempted to keep your distance from both. Which response best reflects the teaching of Romans 12:15?',null,'["Stay neutral with both so you do not get too involved", "Remind the grieving neighbour that others have it worse", "Share in the first neighbour''s joy and grieve alongside the second", "Celebrate the good news but avoid the grieving neighbour to keep things positive"]'::jsonb,2,'Romans 12:15 instructs, ''Rejoice with them that do rejoice, and weep with them that weep,'' calling us to share both the joys and sorrows of others.','The verse names two emotions and asks you to share in each.',null,null,'KJV',array['wisdom','Romans']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Rejoice with them that do rejoice, and weep with them that weep.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-5','wisdom',20,17,9,9,'Proverbs 17:9',3,'A friend once wronged a mutual acquaintance, apologised, and made it right. Now, in a group chat, someone asks whether you know anything about that old falling-out. Which response best reflects the teaching of Proverbs 17:9?',null,'["Let the settled matter rest rather than retelling it", "Bring it up privately with each person in the group", "Hint at the details so people can guess what happened", "Recount the full story so everyone has the facts"]'::jsonb,0,'Proverbs 17:9 says, ''He that covereth a transgression seeketh love; but he that repeateth a matter separateth very friends,'' so repeating the old offence damages friendships.','The proverb contrasts two responses to an offence and what each does to friendship.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that covereth a transgression seeketh love; but he that repeateth a matter separateth very friends.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-6','wisdom',20,3,27,28,'Proverbs 3:27-28',3,'A neighbour asks to borrow a tool you own and are not using; you could hand it over right now. You feel like saying, ''Come back tomorrow,'' simply because it is inconvenient to dig it out. What does Proverbs 3:27-28 counsel here?',null,'["Promise to lend it but quietly hope he forgets", "Help him now, since it is in your power and you have it on hand", "Refuse, because lending to neighbours always causes trouble", "Tell him to come back another day, since your time is your own"]'::jsonb,1,'Proverbs 3:27-28 says, ''Withhold not good from them to whom it is due, when it is in the power of thine hand to do it,'' and not to say ''to morrow I will give; when thou hast it by thee.''','The passage warns against a particular kind of needless delay.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Withhold not good from them to whom it is due, when it is in the power of thine hand to do it. Say not unto thy neighbour, Go, and come again, and to morrow I will give; when thou hast it by thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-7','wisdom',20,27,10,10,'Proverbs 27:10',4,'A crisis hits your household, and your nearest relative lives across the country. A longtime family friend and a nearby neighbour both offer immediate help, but you feel you should only rely on blood relatives. Which response best reflects the teaching of Proverbs 27:10?',null,'["Value the faithful family friend and accept the near neighbour''s help", "Avoid involving anyone so you do not appear weak", "Wait for your distant brother to travel to you before accepting any help", "Decline the friend''s help, since only family should be trusted in hard times"]'::jsonb,0,'Proverbs 27:10 says, ''Thine own friend, and thy father''s friend, forsake not,'' and ''better is a neighbour that is near than a brother far off.''','The proverb compares the value of someone close at hand with a relative who is distant.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Thine own friend, and thy father’s friend, forsake not; neither go into thy brother’s house in the day of thy calamity: for better is a neighbour that is near than a brother far off.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w5-8','wisdom',20,27,14,14,'Proverbs 27:14',4,'You want to thank a friend for a big favour, so you plan to show up at his door at dawn and loudly praise him before he has even woken up. You feel the enthusiasm proves your gratitude. Which response best reflects the teaching of Proverbs 27:14?',null,'["Go ahead, because louder praise always shows greater love", "Repeat the early-morning praise several days in a row for emphasis", "Consider his circumstances, since ill-timed, loud blessing can be received as a curse", "Praise him loudly in public so everyone hears how grateful you are"]'::jsonb,2,'Proverbs 27:14 warns, ''He that blesseth his friend with a loud voice, rising early in the morning, it shall be counted a curse to him,'' so good intentions need wise timing.','The proverb is about how and when a blessing is given, not just whether it is given.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that blesseth his friend with a loud voice, rising early in the morning, it shall be counted a curse to him.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-1','wisdom',20,6,6,8,'Proverbs 6:6-8',1,'You have a flexible remote job and no manager checking in daily. It''s tempting to coast through the slow season and scramble later when the busy months arrive. Which response best reflects the teaching of Proverbs 6:6-8?',null,'["Work steadily and prepare during the slow season, without needing someone to oversee you", "Wait until the busy season starts and then decide how to cope", "Relax fully now, since nobody is watching and the busy season is far off", "Do only what is checked, because effort without a supervisor is wasted"]'::jsonb,0,'Proverbs 6:6-8 points the sluggard to the ant, which has "no guide, overseer, or ruler" yet "provideth her meat in the summer." Diligence and preparation should not depend on being supervised.','Think of a small creature that gathers its food in summer and harvest with no one telling it to.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Go to the ant, thou sluggard; consider her ways, and be wise: Which having no guide, overseer, or ruler, Provideth her meat in the summer, and gathereth her food in the harvest.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-2','wisdom',51,3,23,23,'Colossians 3:23',1,'You''ve been assigned a tedious task at work that your boss will probably never review closely. You''re tempted to do the bare minimum since no one will notice the difference. What does Colossians 3:23 counsel here?',null,'["Put in effort only when it will impress the people above you", "Do the bare minimum, since the effort will go unnoticed", "Do the work wholeheartedly, as though doing it for the Lord rather than for people", "Hand the task off to someone else, since unseen work doesn''t matter"]'::jsonb,2,'Colossians 3:23 says, "whatsoever ye do, do it heartily, as to the Lord, and not unto men." The quality of our work is not meant to depend on human recognition.','The verse names a different audience for your work than your boss.',null,null,'KJV',array['wisdom','Colossians']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And whatsoever ye do, do it heartily, as to the Lord, and not unto men;',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-3','wisdom',20,16,3,3,'Proverbs 16:3',2,'You''re launching a small side project and have been anxiously drafting plans late into the night, relying entirely on your own cleverness. A friend suggests you approach the venture differently. Which response best reflects the teaching of Proverbs 16:3?',null,'["Commit your work to the LORD, trusting Him to establish your plans", "Keep your plans to yourself, since sharing them invites failure", "Rely solely on your own strategy, since success depends only on you", "Abandon planning altogether and simply hope things work out"]'::jsonb,0,'Proverbs 16:3 teaches, "Commit thy works unto the LORD, and thy thoughts shall be established." Planning is paired with entrusting the work to God.','The verse begins with an instruction about what to do with your works.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Commit thy works unto the LORD, and thy thoughts shall be established.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-4','wisdom',42,14,28,30,'Luke 14:28-30',2,'You''re excited about a major home renovation and want to start knocking down walls this weekend. You haven''t yet worked out whether you have the money to finish it. Which response best reflects Jesus'' teaching in Luke 14:28-30?',null,'["Begin the demolition and figure out the budget once you see how it goes", "Avoid all large projects, since any plan might fail", "Sit down first and count the cost to see if you can finish what you start", "Start right away; enthusiasm will carry the project to completion"]'::jsonb,2,'In Luke 14:28-30 Jesus asks, "which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?" Otherwise onlookers would mock the one who "began to build, and was not able to finish." Jesus gives this picture to illustrate counting the cost of following him, and the principle is to count the cost before starting.','Jesus describes someone building a tower and what he does before laying the foundation.',null,null,'KJV',array['wisdom','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? Lest haply, after he hath laid the foundation, and is not able to finish it, all that behold it begin to mock him, Saying, This man began to build, and was not able to finish.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-5','wisdom',59,4,13,15,'James 4:13-15',3,'At dinner you confidently announce a five-year plan: move cities next spring, start a business, and be profitable within a year. A thoughtful friend gently questions how you''re speaking about the future. Which response best reflects the teaching of James 4:13-15?',null,'["Announce your plans boldly, since confidence guarantees success", "Keep your plans vague so no one can hold you to them", "Speak of your plans humbly, saying, \"If the Lord will, we shall live, and do this, or that\"", "Make no plans at all, since planning is forbidden"]'::jsonb,2,'James 4:13-15 reminds us that we "know not what shall be on the morrow" and that life is "a vapour," so we "ought to say, If the Lord will, we shall live, and do this, or that." James corrects presumption, not planning itself.','James compares life to something that appears briefly and vanishes, then gives a phrase to add to our plans.',null,null,'KJV',array['wisdom','James']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Go to now, ye that say, To day or to morrow we will go into such a city, and continue there a year, and buy and sell, and get gain: Whereas ye know not what shall be on the morrow. For what is your life? It is even a vapour, that appeareth for a little time, and then vanisheth away. For that ye ought to say, If the Lord will, we shall live, and do this, or that.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-6','wisdom',49,4,28,28,'Ephesians 4:28',3,'You''re doing well in a steady job, and you''ve begun to think of your earnings purely as a means to upgrade your own lifestyle. A mentor asks you to consider a further purpose for your work. According to Ephesians 4:28, what is one stated purpose of honest labour?',null,'["To prove you are more deserving than others", "To earn status and recognition among peers", "To accumulate enough that you never need to work again", "To have something to give to those in need"]'::jsonb,3,'Ephesians 4:28 urges honest work, "working with his hands the thing which is good, that he may have to give to him that needeth." Labour is meant to provide for generosity, not only for self.','The verse ends by naming someone who benefits from your work besides yourself.',null,null,'KJV',array['wisdom','Ephesians']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Let him that stole steal no more: but rather let him labour, working with his hands the thing which is good, that he may have to give to him that needeth.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-7','wisdom',21,11,4,4,'Ecclesiastes 11:4',4,'For two years you''ve delayed starting a project, waiting for the economy, your schedule and your confidence to all line up perfectly. Each month you find a new reason the conditions aren''t quite right. Which response best reflects the teaching of Ecclesiastes 11:4?',null,'["Keep waiting, because wise people act only when every condition is ideal", "Recognize that endlessly watching for perfect conditions means you will never sow or reap", "Let someone else decide for you so you are not responsible for the timing", "Give up on the project, since uncertain conditions prove it isn''t meant to be"]'::jsonb,1,'Ecclesiastes 11:4 warns, "He that observeth the wind shall not sow; and he that regardeth the clouds shall not reap." Waiting for perfect conditions leads to never acting at all.','The verse pictures a farmer who keeps watching the weather.',null,null,'KJV',array['wisdom','Ecclesiastes']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that observeth the wind shall not sow; and he that regardeth the clouds shall not reap.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w4-8','wisdom',20,21,5,5,'Proverbs 21:5',4,'A colleague urges you to rush into a quick-profit opportunity before thinking it through, promising fast results. You prefer to work out a careful, steady plan instead. What does Proverbs 21:5 contrast here?',null,'["It teaches that both haste and diligence lead to the same outcome", "It teaches that speed always beats careful thought in gaining wealth", "It teaches that thinking about plans is pointless, since outcomes are random", "It teaches that the diligent person''s thoughts lead to plenty, while hastiness leads to want"]'::jsonb,3,'Proverbs 21:5 says, "The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want." Careful, diligent planning is contrasted with haste that ends in lack.','The verse sets two kinds of people against each other: one careful, one in a hurry.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-1','wisdom',50,4,6,7,'Philippians 4:6-7',1,'A routine medical test has you waiting a week for results, and you keep lying awake running through every possible outcome. A friend asks how you are holding up. Which response best reflects the teaching of Philippians 4:6-7?',null,'["Make anxiety your focus, since worrying hard shows you take the situation seriously", "Keep it to yourself, since bringing small worries to God would show a lack of faith", "Bring your concerns to God in prayer with thanksgiving, trusting His peace to keep your heart and mind", "Distract yourself completely and avoid thinking or praying about it until the week is over"]'::jsonb,2,'Paul writes, ''Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God,'' promising that ''the peace of God'' will keep hearts and minds (Philippians 4:6-7).','Notice what Paul says to do ''in every thing'' instead of being anxious.',null,null,'KJV',array['wisdom','Philippians']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God. And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-2','wisdom',40,6,34,34,'Matthew 6:34',1,'Your manager hints that layoffs might come sometime next year. You start spending every evening imagining worst-case scenarios months ahead, and it is draining your joy today. What does Jesus counsel in Matthew 6:34?',null,'["Spend extra time each day rehearsing every possible future problem so nothing surprises you", "Assume the worst will certainly happen and prepare to be miserable", "Worry now so that tomorrow will feel lighter", "Take no anxious thought for tomorrow; each day has enough trouble of its own"]'::jsonb,3,'Jesus says, ''Take therefore no thought for the morrow... Sufficient unto the day is the evil thereof'' (Matthew 6:34), teaching His hearers not to borrow tomorrow''s anxieties.','Jesus says each day already carries enough of its own.',null,null,'KJV',array['wisdom','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-3','wisdom',20,3,5,6,'Proverbs 3:5-6',2,'You are weighing two job offers. You have made spreadsheets and pro-and-con lists, and you are tempted to rely entirely on your own analysis without ever bringing the decision to God. Which response best reflects the teaching of Proverbs 3:5-6?',null,'["Rely only on your own reasoning, since God is not concerned with everyday choices", "Trust God with part of your heart while keeping the final say for your own wisdom", "Acknowledge God only after the decision is made and has turned out well", "Trust the Lord with all your heart, not leaning on your own understanding, and acknowledge Him in the decision"]'::jsonb,3,'Proverbs 3:5-6 says, ''Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths.''','The verse speaks of ''all thine heart'' and ''all thy ways''.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-4','wisdom',59,1,2,4,'James 1:2-4',2,'A long, difficult season at home has tested you, and you are frustrated that it has not ended quickly. You find yourself asking whether hardship has any purpose at all. What does James 1:2-4 counsel here?',null,'["Count it joy, knowing the trying of your faith works patience that makes you mature", "Treat every trial as proof that God has abandoned you", "Pretend the difficulty is not real and refuse to acknowledge it", "Try to escape the trial as fast as possible by any means, since it has no value"]'::jsonb,0,'James writes, ''count it all joy when ye fall into divers temptations; Knowing this, that the trying of your faith worketh patience,'' and urges, ''let patience have her perfect work'' (James 1:2-4).','James connects testing with the growth of a particular virtue.',null,null,'KJV',array['wisdom','James']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'My brethren, count it all joy when ye fall into divers temptations; Knowing this, that the trying of your faith worketh patience. But let patience have her perfect work, that ye may be perfect and entire, wanting nothing.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-5','wisdom',19,37,7,8,'Psalms 37:7-8',3,'A coworker who cuts corners keeps getting praised and promoted while your honest work goes unnoticed. You feel bitterness rising and are tempted to bend the rules yourself. Which response best reflects the teaching of Psalms 37:7-8?',null,'["Rest in the Lord and wait patiently, refusing to fret or let anger push you toward doing evil", "Start cutting corners too, since that is clearly what gets rewarded", "Conclude that honesty is pointless and give up trying to do right", "Let your anger build until you can confront and expose him publicly"]'::jsonb,0,'The psalmist says, ''Rest in the LORD, and wait patiently for him: fret not thyself because of him who prospereth in his way... Cease from anger, and forsake wrath: fret not thyself in any wise to do evil'' (Psalms 37:7-8).','The psalm warns that fretting can lead somewhere worse.',null,null,'KJV',array['wisdom','Psalms']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Rest in the LORD, and wait patiently for him: fret not thyself because of him who prospereth in his way, because of the man who bringeth wicked devices to pass. Cease from anger, and forsake wrath: fret not thyself in any wise to do evil.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-6','wisdom',59,4,13,15,'James 4:13-15',3,'You confidently announce to friends that next year you will move cities, start a business, and be turning a profit within twelve months. One friend gently asks how you are holding those plans before God. Which response best reflects the teaching of James 4:13-15?',null,'["Make plans humbly, recognizing life is like a vapour and saying, ''If the Lord will, we shall live, and do this''", "Boast about the plans, since confidence guarantees success", "Never make any plans at all, since planning is forbidden", "Insist that your future is fully secure because you have worked out every detail"]'::jsonb,0,'James notes ''ye know not what shall be on the morrow'' and that life ''is even a vapour,'' so ''ye ought to say, If the Lord will, we shall live, and do this, or that'' (James 4:13-15).','James does not condemn planning itself, but a certain attitude toward it.',null,null,'KJV',array['wisdom','James']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Go to now, ye that say, To day or to morrow we will go into such a city, and continue there a year, and buy and sell, and get gain: Whereas ye know not what shall be on the morrow. For what is your life? It is even a vapour, that appeareth for a little time, and then vanisheth away. For that ye ought to say, If the Lord will, we shall live, and do this, or that.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-7','wisdom',21,11,4,6,'Ecclesiastes 11:4-6',4,'You have wanted to start a volunteer ministry for years, but you keep postponing because the timing never feels perfect and you fear it might not succeed. Which response best reflects the teaching of Ecclesiastes 11:4-6?',null,'["Wait until every condition is ideal and success is certain before beginning", "Work only in the morning and stop if results do not come quickly", "Give up the idea, since uncertainty means God is against it", "Stop waiting for perfect conditions and sow diligently, since you cannot know which effort will prosper"]'::jsonb,3,'Ecclesiastes says ''He that observeth the wind shall not sow,'' and counsels, ''In the morning sow thy seed, and in the evening withhold not thine hand: for thou knowest not whether shall prosper'' (Ecclesiastes 11:4-6).','Consider what happens to the farmer who keeps watching the weather.',null,null,'KJV',array['wisdom','Ecclesiastes']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that observeth the wind shall not sow; and he that regardeth the clouds shall not reap. As thou knowest not what is the way of the spirit, nor how the bones do grow in the womb of her that is with child: even so thou knowest not the works of God who maketh all. In the morning sow thy seed, and in the evening withhold not thine hand: for thou knowest not whether shall prosper, either this or that, or whether they both shall be alike good.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w7-8','wisdom',20,12,25,25,'Proverbs 12:25',4,'A close friend calls you, weighed down with anxiety about family pressures. You are unsure whether to say anything or simply change the subject. Which response best reflects the teaching of Proverbs 12:25?',null,'["Offer a good, encouraging word, because heaviness bows the heart but a good word makes it glad", "Tell them their feelings are foolish and they should simply stop being anxious", "Point out all the ways their situation could get even worse", "Avoid the topic entirely, since words make no difference to a heavy heart"]'::jsonb,0,'Proverbs 12:25 observes, ''Heaviness in the heart of man maketh it stoop: but a good word maketh it glad,'' showing the lifting power of kind, encouraging speech.','The proverb contrasts what bows the heart with what gladdens it.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Heaviness in the heart of man maketh it stoop: but a good word maketh it glad.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-2','wisdom',58,13,5,5,'Hebrews 13:5',1,'Scrolling social media, you see friends showing off vacations and new homes, and you start feeling dissatisfied with your modest apartment. You catch yourself planning purchases just to keep up. What does Hebrews 13:5 counsel here?',null,'["Contentment only comes once you own as much as your neighbors", "Keep up with others so you don''t feel left behind", "Be content with what you have, trusting that God will never leave you", "Envy is harmless as long as you don''t say it out loud"]'::jsonb,2,'Hebrews 13:5 urges, ''be content with such things as ye have,'' grounding contentment in God''s promise, ''I will never leave thee, nor forsake thee.''','The verse pairs a call to contentment with a promise of God''s presence.',null,null,'KJV',array['wisdom','Hebrews']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-3','wisdom',47,9,7,7,'2 Corinthians 9:7',2,'Your workplace is collecting donations for a coworker''s family after a house fire. You feel pressured by a manager watching who gives, and you''re tempted to give reluctantly just to look good. Which response best reflects the teaching of 2 Corinthians 9:7?',null,'["Give grudgingly, since the attitude doesn''t matter as long as money is given", "Give only because you were told you must", "Decide in your heart what to give and give it cheerfully, not grudgingly", "Give the largest amount so no one questions you"]'::jsonb,2,'2 Corinthians 9:7 says each should give ''as he purposeth in his heart... not grudgingly, or of necessity: for God loveth a cheerful giver.'' The heart behind the gift matters.','The verse focuses on the giver''s attitude more than the amount.',null,null,'KJV',array['wisdom','2 Corinthians']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-4','wisdom',40,6,19,21,'Matthew 6:19-21',2,'You''ve received a sizable bonus and are considering pouring all of it into luxury items. You realize your thoughts have been consumed by acquiring more possessions. Which response best reflects the teaching of Matthew 6:19-21?',null,'["Store up as many earthly goods as possible, since they last forever", "Lay up treasures in heaven rather than on earth, knowing your heart follows your treasure", "Your heart and your treasure are unrelated, so spend however you like", "Earthly possessions are safe from loss if you buy quality items"]'::jsonb,1,'Jesus teaches, ''lay up for yourselves treasures in heaven,'' because earthly goods decay or are stolen, and ''where your treasure is, there will your heart be also'' (Matthew 6:19-21).','Consider what moth, rust, and thieves can and cannot reach.',null,null,'KJV',array['wisdom','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Lay not up for yourselves treasures upon earth, where moth and rust doth corrupt, and where thieves break through and steal: But lay up for yourselves treasures in heaven, where neither moth nor rust doth corrupt, and where thieves do not break through nor steal: For where your treasure is, there will your heart be also.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-5','wisdom',20,3,27,28,'Proverbs 3:27-28',3,'A friend lent you money months ago and you now have enough in your account to repay it. You''re tempted to tell them, ''Check back next month,'' so you can enjoy a little extra cushion. Which response best reflects the teaching of Proverbs 3:27-28?',null,'["Repay them now, since you have it and it is in your power to do good", "Keep the money, since the loan was informal", "Delay repayment, since a friend should be patient indefinitely", "Repay only if they ask several more times"]'::jsonb,0,'Proverbs 3:27-28 says, ''Withhold not good from them to whom it is due,'' and warns against saying ''to morrow I will give; when thou hast it by thee.''','The passage specifically addresses putting someone off when you already have the means.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Withhold not good from them to whom it is due, when it is in the power of thine hand to do it. Say not unto thy neighbour, Go, and come again, and to morrow I will give; when thou hast it by thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-6','wisdom',50,4,11,12,'Philippians 4:11-12',3,'After a job loss, you''ve had to cut back sharply, and you feel your peace depends on your bank balance. You remember a time when money was plentiful and you felt no different inside. Which response best reflects the teaching of Philippians 4:11-12?',null,'["Learn to be content in every state, whether abased or abounding", "Contentment is only possible when you have plenty", "Paul teaches that circumstances must change before peace can come", "Contentment is only possible when you have very little"]'::jsonb,0,'Paul writes, ''I have learned, in whatsoever state I am, therewith to be content,'' knowing both ''how to be abased'' and ''how to abound'' (Philippians 4:11-12). Contentment is learned, not dependent on circumstances.','Paul says contentment is something he ''learned'' across opposite situations.',null,null,'KJV',array['wisdom','Philippians']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Not that I speak in respect of want: for I have learned, in whatsoever state I am, therewith to be content. I know both how to be abased, and I know how to abound: every where and in all things I am instructed both to be full and to be hungry, both to abound and to suffer need.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-7','wisdom',20,6,1,5,'Proverbs 6:1-5',4,'In a moment of enthusiasm, you rashly pledged to stand behind an acquaintance''s financial obligations, and now you realize you are bound by your own words. You''re tempted to put off dealing with it. What does Proverbs 6:1-5 counsel here?',null,'["Act urgently and humbly, going to the person to seek to be released", "Take on additional pledges for others to show good faith", "Avoid the person entirely and hope they forget your promise", "Relax and sleep on it for a few months; the situation will resolve itself"]'::jsonb,0,'Proverbs 6:1-5 says one who becomes ''surety for thy friend'' is ''snared with the words of thy mouth'' and should ''go, humble thyself,'' giving ''not sleep to thine eyes'' until delivered.','The passage uses images of a roe and a bird escaping a hunter.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'My son, if thou be surety for thy friend, if thou hast stricken thy hand with a stranger, Thou art snared with the words of thy mouth, thou art taken with the words of thy mouth. Do this now, my son, and deliver thyself, when thou art come into the hand of thy friend; go, humble thyself, and make sure thy friend. Give not sleep to thine eyes, nor slumber to thine eyelids. Deliver thyself as a roe from the hand of the hunter, and as a bird from the hand of the fowler.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w2-8','wisdom',20,30,8,9,'Proverbs 30:8-9',4,'You''re writing a personal prayer about your finances. Part of you wants to ask for great wealth, while another part fears hardship. Which request best reflects the prayer in Proverbs 30:8-9?',null,'["Ask for poverty, since lack never tempts anyone to wrongdoing", "Ask only for riches so that you never need to trust God", "Ask for great riches, since abundance never draws the heart from God", "Ask for neither poverty nor riches, but enough, lest fullness lead to denying God or want lead to stealing"]'::jsonb,3,'Proverbs 30:8-9 prays, ''give me neither poverty nor riches; feed me with food convenient for me,'' recognizing that being full may lead to denying God and being poor may lead to stealing.','The writer sees spiritual danger at both extremes.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Remove far from me vanity and lies: give me neither poverty nor riches; feed me with food convenient for me: Lest I be full, and deny thee, and say, Who is the LORD? or lest I be poor, and steal, and take the name of my God in vain.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-1','wisdom',40,5,44,44,'Matthew 5:44',1,'A coworker has openly mocked you in meetings and spread unkind rumors about you. A friend suggests you quietly return the favor or at least cut them off entirely. Which response best reflects the teaching of Matthew 5:44?',null,'["Ignore them completely until they apologize first", "Love them, bless them, do good to them and pray for them", "Return the treatment in kind so they learn a lesson", "Gather evidence and expose their faults to the whole team"]'::jsonb,1,'Jesus commands, "Love your enemies, bless them that curse you, do good to them that hate you, and pray for them" (Matthew 5:44). Retaliation, exposure or cold withdrawal run against this command.','Jesus lists four active things to do toward those who mistreat you.',null,null,'KJV',array['wisdom','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you;',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-2','wisdom',59,2,1,4,'James 2:1-4',1,'You help greet people at a community gathering. A well-dressed businessman and a visibly poor man in worn clothes arrive at the same time, and you feel tempted to give the businessman the best seat. What does James 2:1-4 counsel here?',null,'["Let the poor man in only if there are seats left over", "Show no partiality, welcoming both with equal honor", "Seat the businessman up front, since he may support the group", "Ask the poor man to stand at the back so others feel comfortable"]'::jsonb,1,'James warns against holding the faith "with respect of persons," rebuking those who honor the man with the gold ring while telling the poor man in vile raiment, "Stand thou there" (James 2:1-4).','James describes this exact seating situation and calls favoritism being partial.',null,null,'KJV',array['wisdom','James']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'My brethren, have not the faith of our Lord Jesus Christ, the Lord of glory, with respect of persons. For if there come unto your assembly a man with a gold ring, in goodly apparel, and there come in also a poor man in vile raiment; And ye have respect to him that weareth the gay clothing, and say unto him, Sit thou here in a good place; and say to the poor, Stand thou there, or sit here under my footstool: Are ye not then partial in yourselves, and are become judges of evil thoughts?',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-3','wisdom',20,19,17,17,'Proverbs 19:17',2,'A struggling neighbor asks for help buying groceries this week. You hesitate, thinking you''ll never get the money back. Which response best reflects the teaching of Proverbs 19:17?',null,'["Give with pity, trusting that kindness to the poor is lent to the LORD", "Tell the neighbor to rely on someone wealthier", "Help only if the neighbor signs a promise to repay", "Refuse, because money given away is simply lost"]'::jsonb,0,'Proverbs 19:17 says, "He that hath pity upon the poor lendeth unto the LORD; and that which he hath given will he pay him again." Giving to the needy is not lost but entrusted to God.','The verse describes generosity to the poor as a kind of loan, but not to the poor person.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'He that hath pity upon the poor lendeth unto the LORD; and that which he hath given will he pay him again.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-4','wisdom',20,25,21,22,'Proverbs 25:21-22',2,'A former friend who betrayed you is now going through hard times and is short on food. You learn they are hungry and could easily help. Which response best reflects the teaching of Proverbs 25:21-22?',null,'["Give them food and drink, trusting the LORD to reward you", "Help only after they publicly admit what they did", "Tell mutual friends so everyone knows they deserve it", "Wait and let them experience the consequences of their choices"]'::jsonb,0,'Proverbs 25:21-22 instructs, "If thine enemy be hungry, give him bread to eat; and if he be thirsty, give him water to drink," adding that "the LORD shall reward thee."','The passage names both hunger and thirst and tells you what to do about each.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'If thine enemy be hungry, give him bread to eat; and if he be thirsty, give him water to drink: For thou shalt heap coals of fire upon his head, and the LORD shall reward thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-5','wisdom',45,12,17,19,'Romans 12:17-19',3,'A relative cheated you in a family business deal and you are furious. You are considering ways to make them pay without anyone knowing it was you. Which response best reflects the teaching of Romans 12:17-19?',null,'["Take revenge only if you are certain they are guilty", "Refuse to repay evil for evil, seek peace where possible, and leave vengeance to God", "Cut off all contact and warn others to punish them socially", "Repay them quietly in a way that matches the harm they caused"]'::jsonb,1,'Paul writes, "Recompense to no man evil for evil... live peaceably with all men. Dearly beloved, avenge not yourselves... Vengeance is mine; I will repay, saith the Lord" (Romans 12:17-19).','The passage explains who is to repay wrongs.',null,null,'KJV',array['wisdom','Romans']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Recompense to no man evil for evil. Provide things honest in the sight of all men. If it be possible, as much as lieth in you, live peaceably with all men. Dearly beloved, avenge not yourselves, but rather give place unto wrath: for it is written, Vengeance is mine; I will repay, saith the Lord.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-6','wisdom',3,19,33,34,'Leviticus 19:33-34',3,'A family from another country moves into your neighborhood. Some neighbors are cool toward them and make jokes about their accent and customs. Which response best reflects the teaching of Leviticus 19:33-34?',null,'["Be polite but make clear they are guests, not equals", "Treat them as one born among you and love them as yourself", "Join the jokes lightly so you fit in with your neighbors", "Keep your distance until they adapt to local ways"]'::jsonb,1,'Leviticus 19:33-34 commands, "Ye shall not vex him. But the stranger that dwelleth with you shall be unto you as one born among you, and thou shalt love him as thyself."','The passage reminds Israel that they themselves were once strangers in Egypt.',null,null,'KJV',array['wisdom','Leviticus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And if a stranger sojourn with thee in your land, ye shall not vex him. But the stranger that dwelleth with you shall be unto you as one born among you, and thou shalt love him as thyself; for ye were strangers in the land of Egypt: I am the LORD your God.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-7','wisdom',5,24,14,15,'Deuteronomy 24:14-15',4,'You hired a day laborer to do yard work. The job is done, but it would be more convenient to pay him at the end of the month with your other bills. Which response best reflects the teaching of Deuteronomy 24:14-15?',null,'["Pay at month''s end; any delay is fine as long as you pay eventually", "Reduce his pay since he is poor and will accept less", "Pay him the same day, before the sun goes down, since he depends on it", "Pay him only if he reminds you several times"]'::jsonb,2,'Deuteronomy 24:14-15 says not to oppress a poor hired servant: "At his day thou shalt give him his hire, neither shall the sun go down upon it; for he is poor, and setteth his heart upon it."','The passage gives a specific time limit tied to the day''s end.',null,null,'KJV',array['wisdom','Deuteronomy']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Thou shalt not oppress an hired servant that is poor and needy, whether he be of thy brethren, or of thy strangers that are in thy land within thy gates: At his day thou shalt give him his hire, neither shall the sun go down upon it; for he is poor, and setteth his heart upon it: lest he cry against thee unto the LORD, and it be sin unto thee.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('wis-w8-8','wisdom',20,24,17,18,'Proverbs 24:17-18',4,'A rival at work who treated you unfairly has just been publicly reprimanded and demoted. Colleagues invite you to celebrate their downfall over lunch. Which response best reflects the teaching of Proverbs 24:17-18?',null,'["Smile inwardly but avoid saying anything publicly", "Celebrate, since justice has finally been done", "Refuse to rejoice in their fall, guarding even your heart from gladness at it", "Remind everyone of what they did so the lesson sticks"]'::jsonb,2,'Proverbs 24:17-18 warns, "Rejoice not when thine enemy falleth, and let not thine heart be glad when he stumbleth," because it displeases the LORD. This covers inward gladness, not just outward celebration.','The verse addresses not only your words but also your heart.',null,null,'KJV',array['wisdom','Proverbs']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Rejoice not when thine enemy falleth, and let not thine heart be glad when he stumbleth: Lest the LORD see it, and it displease him, and he turn away his wrath from him.',null,null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-1','geography',42,2,51,51,'Luke 2:51',1,'After his visit to the temple at age twelve, the boy Jesus returned with Mary and Joseph to the town marked on the map and was subject unto them. Which town is it?',null,'["Nazareth", "Capernaum", "Bethlehem", "Jericho"]'::jsonb,0,'Luke 2:51 says Jesus went down with his parents and came to Nazareth, where he was subject unto them.','This Galilean hometown later gave Jesus a title: ''of ...''.',null,null,'KJV',array['geography','Nazareth','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he went down with them, and came to Nazareth, and was subject unto them: but his mother kept all these sayings in her heart.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.7021, "lon": 35.2977}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-2','geography',40,2,1,1,'Matthew 2:1',1,'Jesus was born in Bethlehem of Judaea in the days of Herod the king, and wise men from the east came to Jerusalem seeking him. Which marker shows Bethlehem?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Matthew 2:1 records that Jesus was born in Bethlehem of Judaea in the days of Herod the king, and that wise men came from the east to Jerusalem.','Look in the hill country of Judea, just south of Jerusalem.',null,null,'KJV',array['geography','Bethlehem','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now when Jesus was born in Bethlehem of Judaea in the days of Herod the king, behold, there came wise men from the east to Jerusalem,',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.504, "lon": 34.4644, "label": "A"}, {"lat": 31.7043, "lon": 35.2076, "label": "B"}, {"lat": 32.7021, "lon": 35.2977, "label": "C"}, {"lat": 32.8811, "lon": 35.575, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-3','geography',40,4,13,13,'Matthew 4:13',2,'Leaving Nazareth, Jesus came and dwelt in the town marked on the map, upon the sea coast in the borders of Zabulon and Nephthalim. Which town is it?',null,'["Nazareth", "Bethlehem", "Jericho", "Capernaum"]'::jsonb,3,'Matthew 4:13 says that, leaving Nazareth, Jesus came and dwelt in Capernaum, which is upon the sea coast.','This town sits on the northern shore of a freshwater lake.',null,null,'KJV',array['geography','Capernaum','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And leaving Nazareth, he came and dwelt in Capernaum, which is upon the sea coast, in the borders of Zabulon and Nephthalim:',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.8811, "lon": 35.575}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-4','geography',42,7,11,15,'Luke 7:11-15',3,'Jesus raised the only son of a widow as his funeral procession left the gate of a city called Nain. Which marker shows Nain?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Luke 7:11-15 tells how Jesus went into a city called Nain and raised the dead son of a widow, delivering him to his mother.','This village lies in lower Galilee, not far from Nazareth and Mount Tabor.',null,null,'KJV',array['geography','Nain','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And it came to pass the day after, that he went into a city called Nain; and many of his disciples went with him, and much people. Now when he came nigh to the gate of the city, behold, there was a dead man carried out, the only son of his mother, and she was a widow: and much people of the city was with her. And when the Lord saw her, he had compassion on her, and said unto her, Weep not. And he came and touched the bier: and they that bare him stood still. And he said, Young man, I say unto thee, Arise. And he that was dead sat up, and began to speak. And he delivered him to his mother.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.6307, "lon": 35.3501, "label": "A"}, {"lat": 31.7767, "lon": 35.2342, "label": "B"}, {"lat": 31.8717, "lon": 35.4446, "label": "C"}, {"lat": 33.2708, "lon": 35.1961, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-5','geography',42,19,1,5,'Luke 19:1-5',2,'Jesus entered and passed through the city marked on the map, where a chief publican named Zacchaeus climbed a sycomore tree to see him. Which city is it?',null,'["Jericho", "Hebron", "Bethany", "Bethlehem"]'::jsonb,0,'Luke 19:1-5 records that Jesus passed through Jericho, where Zacchaeus climbed a sycomore tree and Jesus called him down.','This ancient city lies in the Jordan valley, near the north end of the Dead Sea.',null,null,'KJV',array['geography','Jericho','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Jesus entered and passed through Jericho. And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich. And he sought to see Jesus who he was; and could not for the press, because he was little of stature. And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way. And when Jesus came to the place, he looked up, and saw him, and said unto him, Zacchæus, make haste, and come down; for to day I must abide at thy house.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.8717, "lon": 35.4446}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-6','geography',43,11,1,1,'John 11:1',3,'Lazarus, whom Jesus raised from the dead, lived in Bethany, the town of Mary and her sister Martha. Which marker shows Bethany?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'John 11:1 introduces Lazarus of Bethany, the town of Mary and her sister Martha.','This village lies just east of Jerusalem, beyond the Mount of Olives.',null,null,'KJV',array['geography','Bethany','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.504, "lon": 34.4644, "label": "A"}, {"lat": 32.5, "lon": 34.8917, "label": "B"}, {"lat": 31.7717, "lon": 35.2559, "label": "C"}, {"lat": 32.8811, "lon": 35.575, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-7','geography',40,4,18,18,'Matthew 4:18',1,'Walking beside the body of water marked on the map, Jesus saw Simon Peter and Andrew casting a net, for they were fishers. Which body of water is it?',null,'["Mount Tabor", "Salt Sea", "Sea of Galilee", "Jordan"]'::jsonb,2,'Matthew 4:18 says Jesus, walking by the sea of Galilee, saw Simon called Peter and Andrew casting a net into the sea.','This freshwater lake lies in the north, fed by the Jordan.',null,null,'KJV',array['geography','Sea of Galilee','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Jesus, walking by the sea of Galilee, saw two brethren, Simon called Peter, and Andrew his brother, casting a net into the sea: for they were fishers.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 32.8189, "lon": 35.59}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-8','geography',40,3,13,13,'Matthew 3:13',2,'Jesus came from Galilee to the Jordan to be baptized by John. Which marker shows the Jordan?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Matthew 3:13 records that Jesus came from Galilee to Jordan unto John, to be baptized of him.','Look for the river running north to south through the rift valley, far from the coast.',null,null,'KJV',array['geography','Jordan','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then cometh Jesus from Galilee to Jordan unto John, to be baptized of him.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.6725, "lon": 35.0233, "label": "A"}, {"lat": 31.7614, "lon": 35.5583, "label": "B"}, {"lat": 31.504, "lon": 34.4644, "label": "C"}, {"lat": 32.0545, "lon": 34.753, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-9','geography',40,26,36,36,'Matthew 26:36',3,'On the night he was betrayed, Jesus went with his disciples to the place marked on the map and told them to sit while he went to pray. Which place is it?',null,'["Nazareth", "Bethlehem", "Gethsemane", "Jericho"]'::jsonb,2,'Matthew 26:36 says Jesus came with his disciples unto a place called Gethsemane and told them to sit while he went to pray.','This garden lay just outside Jerusalem''s eastern wall.',null,null,'KJV',array['geography','Gethsemane','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then cometh Jesus with them unto a place called Gethsemane, and saith unto the disciples, Sit ye here, while I go and pray yonder.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.7794, "lon": 35.2394}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gw-10','geography',40,15,21,22,'Matthew 15:21-22',4,'Jesus departed into the coasts of Tyre and Sidon, where a woman of Canaan begged him to heal her daughter. Which marker shows Tyre?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'Matthew 15:21-22 says Jesus departed into the coasts of Tyre and Sidon, and a woman of Canaan cried to him for her daughter.','This Phoenician port lies on the Mediterranean coast, north of Galilee.',null,null,'KJV',array['geography','Tyre','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then Jesus went thence, and departed into the coasts of Tyre and Sidon. And, behold, a woman of Canaan came out of the same coasts, and cried unto him, saying, Have mercy on me, O Lord, thou Son of David; my daughter is grievously vexed with a devil.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.7767, "lon": 35.2342, "label": "A"}, {"lat": 31.504, "lon": 