insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-5','geography',11,5,1,1,'1 Kings 5:1',1,'The king of the city marked on the map sent his servants unto Solomon when he heard Solomon had been anointed king, for this king was ever a lover of David. Which city is it?',null,'["Tyre", "Beersheba", "Gaza", "Joppa"]'::jsonb,0,'Hiram king of Tyre sent his servants unto Solomon, having heard he was anointed king in his father''s room, for Hiram was ever a lover of David (1 Kings 5:1).','A famous Phoenician seaport north of Israel.',null,null,'KJV',array['geography','Tyre','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Hiram king of Tyre sent his servants unto Solomon; for he had heard that they had anointed him king in the room of his father: for Hiram was ever a lover of David.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 33.2708, "lon": 35.1961}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-6','geography',11,17,9,10,'1 Kings 17:9-10',2,'God sent Elijah to Zarephath, where a widow fed him during the drought. Which marker shows Zarephath?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'The LORD told Elijah to go to Zarephath, which belonged to Zidon, where a widow woman would sustain him (1 Kings 17:9-10).','The text says this town belonged to Zidon, on the Phoenician coast.',null,null,'KJV',array['geography','Zarephath','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Arise, get thee to Zarephath, which belongeth to Zidon, and dwell there: behold, I have commanded a widow woman there to sustain thee. So he arose and went to Zarephath. And when he came to the gate of the city, behold, the widow woman was there gathering of sticks: and he called to her, and said, Fetch me, I pray thee, a little water in a vessel, that I may drink.',null,'{"map": {"view": "land", "kind": "locate", 