insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-9','geography',6,10,12,12,'Joshua 10:12',3,'In the battle to defend Gibeon, Joshua said, ''Sun, stand thou still upon Gibeon.'' Which marker shows Gibeon?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'Joshua spoke to the LORD and said, ''Sun, stand thou still upon Gibeon; and thou, Moon, in the valley of Ajalon'' (Joshua 10:12).','This town lay in the hill country of Benjamin, just north of Jerusalem.',null,null,'KJV',array['geography','Gibeon','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then spake Joshua to the LORD in the day when the LORD delivered up the Amorites before the children of Israel, and he said in the sight of Israel, Sun, stand thou still upon Gibeon; and thou, Moon, in the valley of Ajalon.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.2447, "lon": 34.8408, "label": "A"}, {"lat": 32.5853, "lon": 35.1844, "label": "B"}, {"lat": 31.8475, "lon": 35.1834, "label": "C"}, {"lat": 31.5653, "lon": 34.8492, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gu-10','geography',12,18,13,14,'2 Kings 18:13-14',4,'Hezekiah sent a message of submission to the king of Assyria while he was encamped at the city marked on the map. Which city is it?',null,'["Lachish", "Beth-shan", "Shiloh", "Dan"]'::jsonb,0,'After Sennacherib took the fenced cities of Judah, Hezekiah sent to the king of Assyria to Lachish, saying, ''I have offended'' (2 Kings 18:13-14).','A major fortified city in the lowlands of Judah, southwest of Jerusalem.',null,null,'KJV',array['geography','Lachish','2 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Now in the fourteenth year of king Hezekiah did Sennacherib king of Assyria come up against all the fenced cities of Judah, and took them. And Hezekiah king of Judah sent to the king of Assyria to Lachish, saying, I have offended; return from me: that which thou puttest on me will I bear. And the king of Assyria appointed unto Hezekiah king of Judah three hundred talents of silver and thirty talents of gold.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.5653, "lon": 34.8492}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-1','geography',1,28,12,19,'Genesis 28:12-19',1,'Jacob dreamed of a ladder reaching to heaven and named the place where he slept. Which town is marked on the map?',null,'["Hebron", "Bethel", "Shechem", "Beersheba"]'::jsonb,1,'After dreaming of a ladder set up on the earth that reached to heaven, Jacob called the name of that place Bethel, formerly Luz (Genesis 28:12-19).','The name means ''house of God''.',null,null,'KJV',array['geography','Bethel','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of God ascending and descending on it. And, behold, the LORD stood above it, and said, I am the LORD God of Abraham thy father, and the God of Isaac: the land whereon thou liest, to thee will I give it, and to thy seed; And thy seed shall be as the dust of the earth, and thou shalt spread abroad to the west, and to the east, and to the north, and to the south: and in thee and in thy seed shall all the families of the earth be blessed. And, behold, I am with thee, and will keep thee in all places whither thou goest, and will bring thee again into this land; for I will not leave …',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.9228, "lon": 35.2414}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-2','geography',6,6,2,5,'Joshua 6:2-5',1,'After Israel crossed the Jordan, the LORD told Joshua that this city''s wall would fall down flat when the people shouted. Which city is marked on the map?',null,'["Jericho", "Bethel", "Gibeon", "Shiloh"]'::jsonb,0,'The LORD said, ''I have given into thine hand Jericho,'' and promised that after the trumpets and the shout the wall of the city would fall down flat (Joshua 6:2-5).','Israel marched around this city once a day for six days.',null,null,'KJV',array['geography','Jericho','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And the LORD said unto Joshua, See, I have given into thine hand Jericho, and the king thereof, and the mighty men of valour. And ye shall compass the city, all ye men of war, and go round about the city once. Thus shalt thou do six days. And seven priests shall bear before the ark seven trumpets of rams’ horns: and the seventh day ye shall compass the city seven times, and the priests shall blow with the trumpets. And it shall come to pass, that when they make a long blast with the ram’s horn, and when ye hear the sound of the trumpet, all the people shall shout with a great shout; and the wall of the city shall fall down flat, and the people shall ascend up every man straight before him.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.8717, "lon": 35.4446}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-3','geography',7,16,1,3,'Judges 16:1-3',1,'Samson carried off the doors of the city gate of Gaza. Which marker shows Gaza?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Samson went to Gaza, and at midnight he took the doors of the gate of the city and carried them away (Judges 16:1-3).','Look for a Philistine city near the southern coast.',null,null,'KJV',array['geography','Gaza','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Then went Samson to Gaza, and saw there an harlot, and went in unto her. And it was told the Gazites, saying, Samson is come hither. And they compassed him in, and laid wait for him all night in the gate of the city, and were quiet all the night, saying, In the morning, when it is day, we shall kill him. And Samson lay till midnight, and arose at midnight, and took the doors of the gate of the city, and the two posts, and went away with them, bar and all, and put them upon his shoulders, and carried them up to the top of an hill that is before Hebron.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 31.504, "lon": 34.4644, "label": "A"}, {"lat": 33.249, "lon": 35.652, "label": "B"}, {"lat": 31.8717, "lon": 35.4446, "label": "C"}, {"lat": 32.5036, "lon": 35.5031, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-4','geography',1,11,31,31,'Genesis 11:31',2,'Terah left Ur with Abram, Sarai and Lot, heading for Canaan, but they stopped and dwelt in the city marked on the map. Which city is it?',null,'["Babylon", "Damascus", "Nineveh", "Haran"]'::jsonb,3,'Terah and his family went forth from Ur of the Chaldees to go into Canaan, but they came unto Haran and dwelt there (Genesis 11:31).','This city lies in the north, along the route from Mesopotamia toward Canaan.',null,null,'KJV',array['geography','Haran','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Terah took Abram his son, and Lot the son of Haran his son’s son, and Sarai his daughter in law, his son Abram’s wife; and they went forth with them from Ur of the Chaldees, to go into the land of Canaan; and they came unto Haran, and dwelt there.',null,'{"map": {"view": "east", "kind": "identify", "markers": [{"lat": 36.8644, "lon": 39.0328}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-5','geography',1,15,7,7,'Genesis 15:7',2,'The LORD reminded Abram that He had brought him out of Ur of the Chaldees. Which marker shows Ur?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,2,'The LORD said to Abram, ''I am the LORD that brought thee out of Ur of the Chaldees, to give thee this land'' (Genesis 15:7).','Look in southern Mesopotamia, near the lower Euphrates.',null,null,'KJV',array['geography','Ur','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And he said unto him, I am the LORD that brought thee out of Ur of the Chaldees, to give thee this land to inherit it.',null,'{"map": {"view": "east", "kind": "locate", "markers": [{"lat": 32.1892, "lon": 48.2578, "label": "A"}, {"lat": 29.8488, "lon": 31.253, "label": "B"}, {"lat": 30.9622, "lon": 46.1044, "label": "C"}, {"lat": 36.8644, "lon": 39.0328, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-6','geography',1,23,19,19,'Genesis 23:19',2,'Abraham buried Sarah in the cave of Machpelah, near the city of Hebron. Which marker shows Hebron?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,1,'Abraham buried Sarah in the cave of the field of Machpelah before Mamre, ''the same is Hebron in the land of Canaan'' (Genesis 23:19).','It lies in the hill country of Judah, south of Jerusalem.',null,null,'KJV',array['geography','Hebron','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And after this, Abraham buried Sarah his wife in the cave of the field of Machpelah before Mamre: the same is Hebron in the land of Canaan.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.2136, "lon": 35.2819, "label": "A"}, {"lat": 31.5251, "lon": 35.1022, "label": "B"}, {"lat": 33.249, "lon": 35.652, "label": "C"}, {"lat": 31.2447, "lon": 34.8408, "label": "D"}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-7','geography',1,21,31,31,'Genesis 21:31',3,'Abraham and Abimelech made a covenant at a well, and Abraham named the place after the oath they swore. Which place is marked on the map?',null,'["Hebron", "Kadesh-barnea", "Gaza", "Beersheba"]'::jsonb,3,'Abraham called that place Beersheba ''because there they sware both of them'' (Genesis 21:31).','Its name is linked to a well and an oath, in the Negev.',null,null,'KJV',array['geography','Beersheba','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'Wherefore he called that place Beer-sheba; because there they sware both of them.',null,'{"map": {"view": "land", "kind": "identify", "markers": [{"lat": 31.2447, "lon": 34.8408}]}}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('geo-gx-8','geography',1,33,18,18,'Genesis 33:18',3,'Returning from Padanaram, Jacob came to Shalem, a city of Shechem, and pitched his tent before it. Which marker shows Shechem?',null,'["Marker A", "Marker B", "Marker C", "Marker D"]'::jsonb,0,'Jacob came to Shalem, a city of Shechem in the land of Canaan, when he came from Padanaram, and pitched his tent before the city (Genesis 33:18).','Look in the central hill country, north of Bethel.',null,null,'KJV',array['geography','Shechem','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text; automatic checks (reference exists, at most 15 verses, keywords found in the KJV passage, geography places and views valid, locate markers far enough apart, place named in the passage); independent AI review against the KJV text (Claude Opus 5.5), with flagged items fixed and re-reviewed or dropped. Hidden-object areas were drawn by hand on the reviewed illustrations and checked visually; every object is checked against a KJV passage that names it. Not read individually by a person. See tests/review/modes."}'::jsonb,'And Jacob came to Shalem, a city of Shechem, which is in the land of Canaan, when he came from Padan-aram; and pitched his tent before the city.',null,'{"map": {"view": "land", "kind": "locate", "markers": [{"lat": 32.2136, "lon": 35.2819, "label": "A"}, {"lat": 32.5853, "lon": 35.1844, "label": "B"}, {"lat": 31.7767, "lon": 35.2342, "label": "C"}, {"lat": 33.249, "lon": 35.652, "label": 