insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs, extra) values ('hid-lost_sheep-ninety_nine','hidden',42,15,4,4,'Luke 15:4',2,'Find the ninety and nine left behind.',null,'["Area 1", "Area 2", "Area 3", "Area 4"]'::jsonb,1,'He doth leave the ninety and nine in the wilderness, and go after that which is lost (Luke 15:4).','Look for something mentioned in Luke 15:4.','lost_sheep','A shepherd carries a lost sheep on his shoulders across the hills while the rest of the flock waits in the distance.','KJV',array['hidden','lost_sheep','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending", "ai_review": "passed", "ai_reviewed_at": "2026-11-22", "review_method": "AI-drafted with Claude Opus 5.5 from the KJV text for illustration batch 2; automatic checks (reference exists, keywords found in the KJV passage, tap areas within the picture); independent AI review against the KJV text (Claude Opus 5.5), 22 of 165 items flagged and fixed then re-reviewed, 1 dropped. Hidden-object areas were drawn by hand on a 10% grid over each illustration and checked visually on a contact sheet. See tests/review/illustrations2."}'::jsonb,'What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?',null,'{"boxes": [{"area": 0, "box": [38, 8, 17, 34]}, {"area": 1, "box": [3, 36, 24, 13]}, {"area": 2, "box": [65, 8, 35, 22]}, {"area": 3, "box": [37, 5, 26, 88]}]}'::jsonb) on conflict (id) do nothing;
